package com.ironman.friday.utils\n\nimport android.content.Context\nimport android.content.res.Configuration\nimport java.util.Locale\n\nclass LanguageManager(val context: Context) {\n\n    companion object {\n        const val LANGUAGE_ENGLISH = \"en\"\n        const val LANGUAGE_TAMIL = \"ta\"\n    }\n\n    fun setLanguage(languageCode: String) {\n        val locale = Locale(languageCode)\n        Locale.setDefault(locale)\n\n        val config = Configuration()\n        config.locale = locale\n\n        context.resources.updateConfiguration(config, context.resources.displayMetrics)\n\n        // Save preference\n        PreferencesManager(context).setLanguage(languageCode)\n    }\n\n    fun getCurrentLanguage(): String {\n        return PreferencesManager(context).getLanguage()\n    }\n\n    fun getAvailableLanguages(): Map<String, String> {\n        return mapOf(\n            LANGUAGE_ENGLISH to \"English\",\n            LANGUAGE_TAMIL to \"தமிழ்\" // Tamil\n        )\n    }\n}\n